                src = trkpt.find('src')
                if src is not None and src.text:
                    track_point.source = src.text

                link = trkpt.find('link')
                if link is not None:
                    track_point.link = link.get('href')
                    track_point.link_text = link.text
                    track_point.link_type = link.get('type')

                sym = trkpt.find('sym')
                if sym is not None and sym.text:
                    track_point.symbol = sym.text

                type_elem = trkpt.find('type')
                if type_elem is not None and type_elem.text:
                    track_point.type = type_elem.text

                fix = trkpt.find('fix')
                if fix is not None and fix.text:
                    track_point.type_of_gpx_fix = fix.text

                sat = trkpt.find('sat')
                if sat is not None and sat.text:
                    track_point.satellites = int(sat.text)

                vdop = trkpt.find('vdop')
                if vdop is not None and vdop.text:
                    track_point.vertical_dilution = float(vdop.text)

                hdop = trkpt.find('hdop')
                if hdop is not None and hdop.text:
                    track_point.horizontal_dilution = float(hdop.text)

                pdop = trkpt.find('pdop')
                if pdop is not None and pdop.text:
                    track_point.position_dilution = float(pdop.text)

                ageofdgpsdata = trkpt.find('ageofdgpsdata')
                if ageofdgpsdata is not None and ageofdgpsdata.text:
                    track_point.age_of_dgps_data = float(ageofdgpsdata.text)

                dgpsid = trkpt.find('dgpsid')
                if dgpsid is not None and dgpsid.text:
                    track_point.dgps_id = int(dgpsid.text)

                # Parse extensions
                extensions = trkpt.find('extensions')
                if extensions is not None:
                    track_point.extensions = list(extensions)

                segment.points.append(track_point)

            # Parse segment extensions
            extensions = trkseg.find('extensions')
            if extensions is not None:
                segment.extensions = list(extensions)

            track.segments.append(segment)

        # Parse track extensions
        extensions = trk.find('extensions')
        if extensions is not None:
            track.extensions = list(extensions)

        gpx.tracks.append(track)

    # Parse top-level extensions
    extensions = root.find('extensions')
    if extensions is not None:
        gpx.extensions = list(extensions)

    return gpx
